"""Presentation components for the bilingual White Office website."""
import html

from localize_site import SITE_URL
from site_previews import preview

esc = html.escape


def artwork(app, root=''):
    return f'''<div class="artwork art-{app['slug']}"><div class="artwork-bar"><span class="window-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>{app['name']}</span><span aria-hidden="true">↗</span></div>{preview(app['slug'])}</div>'''


def card(app, root=''):
    return f'''<a class="app-card card-{app['slug']}" href="{root}apps/{app['slug']}.html" style="--accent:{app['accent']}"><div class="card-top"><img src="{root}assets/icons/{app['slug']}.png" width="52" height="52" alt=""><span class="card-arrow" aria-hidden="true">↗</span></div><div class="card-heading"><h3>{app['name']}</h3><span>{app['role']}</span></div><p>{esc(app['tagline'])}</p><div class="card-art" aria-hidden="true">{artwork(app, root)}</div><span class="card-link">Meet {app['name']} <span aria-hidden="true">→</span></span></a>'''


def closing(root=''):
    return f'''<section class="wrap closing"><div class="closing-orbit" aria-hidden="true"><span></span><span></span><span></span><img src="{root}assets/whiteoffice-mark.svg" width="96" height="96" alt=""></div><div><p class="eyebrow">MAKE YOURSELF AT HOME</p><h2>Your next project<br>starts here.</h2><p>Choose your apps. Find your flow.</p><a class="btn" href="{root}download.html">Get White Office <span aria-hidden="true">↗</span></a></div></section>'''


def explorer(apps):
    tabs = ''.join(f'''<button type="button" id="tab-{a['slug']}" role="tab" aria-selected="{str(i == 0).lower()}" aria-controls="panel-{a['slug']}" tabindex="{0 if i == 0 else -1}"><img src="assets/icons/{a['slug']}.png" width="30" height="30" alt=""><span>{a['name']}<small>{a['role']}</small></span><span class="tab-arrow" aria-hidden="true">↗</span></button>''' for i, a in enumerate(apps))
    panels = ''.join(f'''<div class="explorer-panel" id="panel-{a['slug']}" role="tabpanel" aria-labelledby="tab-{a['slug']}" tabindex="0" {'hidden' if i else ''}><div class="explorer-copy"><span class="section-number">0{i+1} / 04</span><h3>{esc(a['tagline'])}</h3><p>{esc(a['lede'])}</p><a class="text-link" href="apps/{a['slug']}.html">Meet {a['name']} <span aria-hidden="true">↗</span></a><p class="illustration-label">Illustration</p></div><div class="explorer-art">{artwork(a)}</div></div>''' for i, a in enumerate(apps))
    return f'''<section class="studio" id="apps"><div class="wrap section"><div class="section-heading"><div><p class="eyebrow">01 / EXPLORE YOUR WORKSPACE</p><h2>Different tools.<br>One creative space.</h2></div><p>Choose a tool to explore what you can make.</p></div><div class="app-tabs" role="tablist" aria-label="Explore an illustrative app preview">{tabs}</div>{panels}</div></section>'''


def home(apps):
    dock = ''.join(f'''<a href="apps/{a['slug']}.html"><img src="assets/icons/{a['slug']}.png" width="58" height="58" alt=""><span>{a['name']}</span></a>''' for a in apps)
    return f'''<section class="hero-stage"><div class="wrap"><div class="hero-copy"><h1>A little space.<br><em>Endless possibility.</em></h1><p class="lede">Four independent apps for the things you want to create.<br>Write. Calculate. Present. Bring it all together.</p><div class="cta"><a class="btn" href="download.html">Get White Office <span aria-hidden="true">↗</span></a><a class="btn ghost" href="#apps">Explore the apps <span aria-hidden="true">↓</span></a></div><p class="hero-note">Windows, macOS &amp; Linux <span>·</span> No account needed</p></div><div class="hero-installation"><div class="orbital-line orbit-one" aria-hidden="true"></div><div class="orbital-line orbit-two" aria-hidden="true"></div><div class="floating-label label-one"><span class="status-dot"></span> Made for your ideas</div><div class="floating-label label-two">Local files. Your control.</div><div class="floating-piece piece-sheet" aria-hidden="true">{artwork(apps[1])}</div><div class="floating-piece piece-document" aria-hidden="true">{artwork(apps[0])}</div><div class="floating-piece piece-slide" aria-hidden="true">{artwork(apps[2])}</div><div class="app-dock">{dock}</div><span class="installation-caption">Illustration</span></div></div></section><div class="trust-strip"><div class="wrap"><span>DESIGNED AROUND YOU</span><b>Works offline</b><b>Familiar file formats</b><b>Native performance</b></div></div>{explorer(apps)}<section class="wrap section principles-section"><div class="section-heading"><div><p class="eyebrow">02 / A DIFFERENT KIND OF OFFICE</p><h2>More room for ideas.<br>Less in the way.</h2></div><p>Your files belong on your desk. Your attention belongs on your ideas.</p></div><div class="principle-layout"><article class="local-feature"><div class="local-art" aria-hidden="true"><div class="file-tile"><span>.docx</span></div><div class="file-tile"><span>.xlsx</span></div><div class="file-tile"><span>.pdf</span></div><span class="local-ring"></span></div><div><span class="section-number">01</span><h3>Your work stays with you</h3><p>Create and edit local files without an account. Keep working when the connection doesn’t.</p></div></article><div class="principle-stack"><article><span class="section-number">02</span><h3>At home on your computer</h3><p>Native Rust applications for everyday desktop work. Open an app and get straight to it.</p><div class="platform-pills"><span>Windows</span><span>macOS</span><span>Linux</span></div></article><article><span class="section-number">03</span><h3>Files you already know</h3><p>Work with DOCX, XLSX, PPTX and PDF. Bring your existing files and export work you can share.</p></article></div></div></section>{closing()}'''


def apps_page(apps):
    return f'''<section class="page-intro wrap"><p class="eyebrow">THE WHITE OFFICE COLLECTION</p><div class="intro-row"><h1>Good tools.<br><em>Great possibilities.</em></h1><p class="lede">Write something worth reading. Make sense of the numbers. Tell a better story. Bring every page together.</p></div></section><section class="wrap collection"><div class="app-grid">{''.join(card(a, '../') for a in apps)}</div><p class="illustration-label">Illustrative previews. Explore each app for features and supported formats.</p></section>{closing('../')}'''


def app_page(app, apps):
    features = ''.join(f'<article><span class="section-number">0{i+1}</span><h3>{esc(t)}</h3><p>{esc(d)}</p></article>' for i, (t, d) in enumerate(app['features']))
    others = ''.join(f'''<a class="related-app" href="{a['slug']}.html"><img src="../assets/icons/{a['slug']}.png" width="48" height="48" alt=""><span><strong>{a['name']}</strong><small>{a['role']}</small></span><span aria-hidden="true">↗</span></a>''' for a in apps if a != app)
    return f'''<section class="product-intro product-{app['slug']}" style="--accent:{app['accent']}"><div class="wrap"><a class="back-link" href="index.html">← All apps</a><div class="product-hero"><div><div class="app-title"><img src="../assets/icons/{app['slug']}.png" width="64" height="64" alt=""><span>{app['role']}</span></div><h1>{app['name']}<span>{esc(app['tagline'])}</span></h1><p class="lede">{esc(app['lede'])}</p><div class="cta"><a class="btn" href="../download.html#{app['slug']}">Get {app['name']} ↗</a></div></div><div class="product-art">{artwork(app, '../')}<p class="illustration-label">Illustration</p></div></div></div></section><div class="format-strip"><div class="wrap"><p class="eyebrow">FAMILIAR FILES</p><p>{esc(app['formats'])}</p></div></div><section class="wrap section"><div class="section-heading"><h2>Made for your<br>everyday work.</h2><p>Start with what you need.<br>There’s room for the rest.</p></div><div class="feature-grid">{features}</div></section><section class="wrap development-note"><span class="status-dot"></span><div><h2>A work in progress, ready to explore.</h2><p>Desktop packages are listed on the download page when available. Compatibility and features continue to evolve; keep a copy of important files when trying a new build.</p></div></section><section class="wrap section"><div class="section-heading"><h2>The rest of your desk.</h2></div><div class="related-grid">{others}</div></section>'''


def downloads(apps, catalog):
    cards = []
    for a in [{'slug': 'whiteoffice-launcher', 'name': 'Launcher', 'role': 'Install & update the suite'}, *apps]:
        data = catalog.get(a['slug'], {})
        assets = data.get('assets', {})
        platforms = []
        for os, name, arch, formats in (('windows', 'Windows', 'x64', (('windows-x64.msi', 'Installer'), ('windows-x64-portable.zip', 'Portable ZIP'))), ('macos', 'macOS', 'Apple silicon + Intel', (('macos-universal.tar.gz', 'Universal archive'),)), ('linux', 'Linux', 'x86_64', (('linux-x86_64.tar.gz', 'Linux archive'),))):
            links = []
            for suffix, label in formats:
                asset = assets.get(suffix)
                if asset:
                    links.append(f'''<a class="download-link" href="{SITE_URL}/dl/{esc(asset['name'])}" aria-label="Download {a['name']} {esc(data['version'])} {os} {label}"><span>{label}<small>{asset['size'] / 1e6:.1f} MB</small></span><span aria-hidden="true">↓</span></a>''')
            platforms.append(f'''<div class="platform-packages" data-platform="{os}"><div class="platform-name"><h3>{name}</h3><span>{arch}</span></div>{''.join(links) or '<p class="unavailable">Not available yet</p>'}</div>''')
        icon = f"icons/{a['slug']}.png" if a['slug'] != 'whiteoffice-launcher' else 'whiteoffice-mark.svg'
        cards.append(f'''<article class="download-card {'launcher-card' if a['slug'] == 'whiteoffice-launcher' else ''}" id="{a['slug']}"><div class="download-card-heading"><img src="assets/{icon}" width="48" height="48" alt=""><div><h2>{a['name']}</h2><p>{esc(a['role'])}</p></div><code>{esc(data.get('version', 'Coming soon'))}</code></div><div class="package-grid">{''.join(platforms)}</div></article>''')
    return f'''<section class="wrap page-intro download-intro"><p class="eyebrow">MAKE ROOM FOR GOOD WORK</p><div class="intro-row"><h1>Your next chapter.<br><em>One download away.</em></h1><p class="lede">Get the launcher to install and update your apps, or choose an individual app. No account. Just your next project.</p></div></section><section class="wrap download-section"><div class="download-controls"><div class="platform-filter" role="group" aria-label="Filter downloads by operating system" hidden><button type="button" data-os="all" aria-pressed="true">All platforms</button><button type="button" data-os="windows" aria-pressed="false">Windows</button><button type="button" data-os="macos" aria-pressed="false">macOS</button><button type="button" data-os="linux" aria-pressed="false">Linux</button></div><p id="download-status" aria-live="polite">BUILDS FOR EVERY DESK</p></div><div class="downloads">{''.join(cards)}</div><p class="download-note">Available packages are listed per release. A missing platform means a package for that version is not available yet.</p></section><section class="wrap section"><div class="section-heading"><h2>A few things before you start.</h2></div><div class="setup-steps"><article><span class="section-number">01</span><h3>Pick your package</h3><p>On Windows, use the MSI installer for shortcuts and file associations, or extract the portable ZIP. macOS and Linux downloads are archives.</p></article><article><span class="section-number">02</span><h3>Keep your files close</h3><p>Work with local documents. These are early builds, so keep backups of important files while trying them out.</p></article><article><span class="section-number">03</span><h3>Check before opening</h3><p>Packages are unsigned. Your operating system may show a security prompt. Verify the download source and file checksum before running it.</p><a class="text-link" href="{SITE_URL}/dl/SHA256SUMS.txt">View SHA-256 checksums ↗</a></article></div></section>'''
